DO $$BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END$$;
DO $$BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END$$;
DO $$BEGIN CREATE ROLE service_role NOLOGIN BYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END$$;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth, public TO authenticated, anon, service_role;
CREATE TABLE roles(id uuid primary key default gen_random_uuid(), name text);
CREATE TABLE users_profile(id uuid primary key default gen_random_uuid(), auth_user_id uuid, role_id uuid references roles);
CREATE TABLE companies(id uuid primary key default gen_random_uuid(), name text);
CREATE TABLE contacts(id uuid primary key default gen_random_uuid(), name text);
CREATE TABLE phone_calls(id uuid primary key default gen_random_uuid(), summary text);
CREATE TABLE meetings(id uuid primary key default gen_random_uuid(), title text);
CREATE TABLE tasks(id uuid primary key default gen_random_uuid(), title text);
CREATE TABLE project_notes(id uuid primary key default gen_random_uuid(), author_id uuid, note text);
CREATE TABLE project_documents(id uuid primary key default gen_random_uuid(), uploaded_by uuid, name text);
CREATE TABLE company_documents(id uuid primary key default gen_random_uuid(), uploaded_by uuid, name text);
CREATE TABLE project_contacts(id uuid primary key default gen_random_uuid(), role text);
CREATE TABLE email_threads(id uuid primary key default gen_random_uuid(), subject text, company_id uuid);
CREATE TABLE email_thread_access(thread_id uuid, user_id uuid, mailbox_email text);
CREATE TABLE emails(id uuid primary key default gen_random_uuid(), thread_id uuid, company_id uuid);
CREATE TABLE email_attachments(id uuid primary key default gen_random_uuid(), email_id uuid, filename text);
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated, service_role;
GRANT SELECT ON roles, users_profile, email_thread_access TO authenticated;
CREATE OR REPLACE FUNCTION public.crm_role_of(_auth_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT lower(r.name) FROM public.users_profile up JOIN public.roles r ON r.id = up.role_id WHERE up.auth_user_id = _auth_user LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.current_profile_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT id FROM public.users_profile WHERE auth_user_id = auth.uid() LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.is_owner_role(_auth_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT EXISTS (SELECT 1 FROM public.users_profile up JOIN public.roles r ON r.id = up.role_id WHERE up.auth_user_id = _auth_user AND lower(r.name) IN ('owner','tulajdonos','admin','superadmin')) $$;
CREATE OR REPLACE FUNCTION public.is_email_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT EXISTS (SELECT 1 FROM public.users_profile up JOIN public.roles r ON r.id = up.role_id WHERE up.auth_user_id = _user_id AND lower(coalesce(r.name,'')) IN ('owner','tulajdonos','admin','superadmin')) $$;
CREATE OR REPLACE FUNCTION public.can_access_email_thread(_thread_id uuid, _user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT public.is_email_admin(_user_id) OR EXISTS (SELECT 1 FROM public.email_thread_access a WHERE a.thread_id = _thread_id AND a.user_id = _user_id) $$;
DO $$DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','contacts','phone_calls','meetings','tasks','project_notes','project_documents','company_documents','project_contacts','email_threads','emails','email_attachments'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); END LOOP; END$$;
CREATE POLICY email_attachments_select_per_user ON public.email_attachments FOR SELECT TO authenticated USING ((is_email_admin(auth.uid()) OR (EXISTS ( SELECT 1 FROM emails e WHERE ((e.id = email_attachments.email_id) AND (e.thread_id IS NOT NULL) AND can_access_email_thread(e.thread_id, auth.uid()))))));
CREATE POLICY email_threads_select_per_user ON public.email_threads FOR SELECT TO authenticated USING (can_access_email_thread(id, auth.uid()));
CREATE POLICY emails_select_per_user ON public.emails FOR SELECT TO authenticated USING ((is_email_admin(auth.uid()) OR ((thread_id IS NOT NULL) AND can_access_email_thread(thread_id, auth.uid()))));
